def _snapshot_windows(
    self, units: list[dict]
) -> tuple[list[dict], list[list[tuple[int, int, int]]], list[list[str]]]:
    """Fingerprint the held snapshot: global windows, per-unit bounds/lines.

    Sealed units are exactly covered by their preserved windows and are
    re-authenticated against the bytes. A non-sealed unit's preserved
    prefix is verified and the grown tail gets one fresh window. Record
    lines are decoded once. A half-line or hash mismatch is ``ValueError``.
    """
    windows: list[dict] = []
    all_bounds: list[list[tuple[int, int, int]]] = []
    all_lines: list[list[str]] = []
    for unit in units:
        try:
            with open(unit["path"], "rb") as handle:
                raw = handle.read()
        except FileNotFoundError:
            if not unit["sealed"]:
                raw = b""
            else:
                raise

        bounds: list[tuple[int, int, int]] = []
        running = 0
        parts = unit["parts"]
        if parts:
            if not st.verify_prefix_windows(unit["path"], parts):
                raise ValueError("corrupt audit segment")
            for part in parts:
                bounds.append((running, running + part["size"], len(windows)))
                windows.append(dict(part))
                running += part["size"]
            if unit["sealed"] and running != len(raw):
                raise ValueError("corrupt audit segment")
        if running < len(raw):
            # Grown tail of the active/legacy unit.
            bounds.append((running, len(raw), len(windows)))
            windows.append(
                {
                    "name": unit["name"],
                    "size": len(raw) - running,
                    "sha256": _sha256(raw[running:]),
                }
            )
        all_bounds.append(bounds)
        all_lines.append(rec.split_records(raw.decode(_ENCODING)))
    return windows, all_bounds, all_lines

def _collect_range(
    self,
