    picked: list[dict] = []
    start_prev = ""
    count = 0
    for bounds, lines in zip(unit_bounds, unit_lines):
        pos = 0
        for line in lines:
            length = len((line + "\n").encode(_ENCODING))
            line_start, line_end = pos, pos + length
            record = rec.parse_line(line)
            order = pf.window_for_offset(bounds, line_start, line_end)
