# ---------------------------------------------------------------------------
# Window placement helpers (shared with the exporter)
# ---------------------------------------------------------------------------


def window_for_offset(
    bounds: list[tuple[int, int, int]], line_start: int, line_end: int
) -> int:
    """Return the window order containing a record, or raise on straddle.

    ``bounds`` is ``[(byte_start, byte_end, window_order), ...]`` for one
    unit. Windows only ever concatenate whole records, so a record may not
    straddle a window boundary.
    """
    for lo, hi, order in bounds:
        if line_start >= lo and line_end <= hi:
            return order
        if line_start >= lo and line_start < hi:
            # Started inside this window but runs past its end.
            raise ValueError("record straddles a segment window boundary")
    raise ValueError("record lies outside any verification window")


def bounds_start(bounds: list[tuple[int, int, int]], order: int) -> int:
    for lo, _hi, bound_order in bounds:
        if bound_order == order:
            return lo
    raise ValueError("record lies outside any verification window")


